1092	export async function chopTrees(bot, opts = {}, ctx = {}) {
1093	  const count = opts.count ?? 8;
1094	  const maxDistance = opts.maxDistance ?? 48;
1095	
1096	  // (9) Axe is optional here — hand-chopping works, just slower. Best-effort
1097	  // only: a failed ensureTool() must never abort a chop task.
1098	  //
1099	  // opts._skipEnsureTool is an internal-only escape hatch: ensureTool's own
1100	  // craft chain bootstraps missing logs via ensureLogs() -> chopTrees(), and
1101	  // without this flag that would recurse forever (chopTrees calls
1102	  // ensureTool('axe') -> craftToolChain -> ensurePlanksAndSticks ->
1103	  // ensureLogs -> chopTrees -> ensureTool('axe') -> ...). Never set this
1104	  // from outside skills.js.
1105	  if (!opts._skipEnsureTool) {
1106	    await ensureTool(bot, { kind: 'axe' }, ctx).catch((err) => {
1107	      ctx.log?.('warn', `chopTrees: ensureTool(axe) failed, hand-chopping instead: ${err.message}`);
1108	    });
1109	  }
1110	
1111	  const choppedTrees = [];
1112	  const collectedAll = [];
1113	  const skippedKeys = new Set();
1114	  const maxIterations = count * 4 + 20;
1115	  let iterations = 0;
1116	  let consecutiveStalls = 0;
1117	
1118	  while (choppedTrees.length < count && iterations < maxIterations) {
1119	    iterations++;
1120	    if (ctx.isCancelled?.()) break;
1121	    await checkHealthRetreat(bot, ctx);
1122	    ctx.setDetail?.(`chopping tree ${choppedTrees.length + 1}/${count}`);
1123	
1124	    const base = bot.findBlock({
1125	      point: bot.entity.position,
1126	      maxDistance,
1127	      // mineflayer's findBlock calls this matcher twice per candidate: once
1128	      // during the palette pre-filter with a synthetic Block.fromStateId
1129	      // that has position === null, and once for real with the actual
1130	      // block (position set). Guard b.position before keying on it, or the
1131	      // pre-filter call throws "Cannot read properties of null (reading
1132	      // 'x')" the instant a nearby section's palette contains a log type.
1133	      matching: (b) =>
1134	        /_log$/.test(b.name) && (!b.position || (!skippedKeys.has(posKey(b.position)) && !isPoisoned(ctx, b.position))),
1135	    });
1136	    if (!base) {
1137	      ctx.log?.('warn', `chopTrees: no more *_log blocks within ${maxDistance} blocks`);
1138	      break;
1139	    }
1140	    const key = posKey(base.position);
1141	    const basePos = base.position.clone();
1142	
1143	    // (3) CAMP PROTECT RADIUS — never even select a target this close to
1144	    // camp; matches overseer.mjs's own CHOP QUARANTINE ENFORCER center/
1145	    // radius exactly, but proactive instead of reactive-kill. Exception:
1146	    // tribe-planted groves (zones.json entries named "grove*", e.g. grove_1)
1147	    // sit INSIDE this radius on purpose and must stay choppable — a tight
1148	    // zone-box carve-out, not a loosening of the quarantine itself.
1149	    const campDx = basePos.x - CAMP_PROTECT_CENTER.x;
1150	    const campDz = basePos.z - CAMP_PROTECT_CENTER.z;
1151	    if (Math.hypot(campDx, campDz) < CAMP_PROTECT_RADIUS && !isInGroveZone(basePos)) {
1152	      skippedKeys.add(key);
1153	      ctx.log?.(
1154	        'warn',
1155	        `chopTrees: skipping ${key} — inside camp quarantine (<${CAMP_PROTECT_RADIUS} of (${CAMP_PROTECT_CENTER.x},${CAMP_PROTECT_CENTER.z}))`
1156	      );
1157	      continue;
1158	    }
1159	
1160	    // (3) NO-GO ZONES — never select a chop target inside one, same rule
1161	    // mineBlocks already enforces on its own targets.
1162	    if (isInNoGoZone(basePos, ctx)) {
1163	      skippedKeys.add(key);
1164	      continue;
1165	    }
1166	
1167	    // (3) NATURAL TREE CHECK — see hasLeavesAboveTop() above.
1168	    if (!hasLeavesAboveTop(bot, basePos)) {
1169	      skippedKeys.add(key);
1170	      ctx.log?.('warn', `chopTrees: skipping ${key} — no leaves within 4 blocks above top log (built structure, not tree)`);
1171	      continue;
1172	    }
1173	
1174	    // Per-tree abandon flag — see abandonableCtx above. Fresh object every
1175	    // iteration so a previous tree's flag can never mute the current one.
1176	    const abandonFlag = { abandoned: false };
1177	    const stepCtx = abandonableCtx(ctx, abandonFlag);
1178	
1179	    let watchdog;
1180	    try {
1181	      watchdog = await runTargetWithWatchdog(bot, stepCtx, 25000, async () => {
1182	        stepCtx.setTargetPos?.(basePos);
1183	        await gotoLoop(
1184	          bot,
1185	          new goals.GoalGetToBlock(basePos.x, basePos.y, basePos.z),
1186	          { timeoutMs: 20000, maxAttempts: 3 },
1187	          stepCtx
1188	        );
1189	
1190	        const belowPos = basePos.offset(0, -1, 0);
1191	        let current = bot.blockAt(basePos);
1192	        let logsFelled = 0;
1193	        const preDigSnapshot = snapshotInventory(bot);
1194	
1195	        while (current && /_log$/.test(current.name)) {
1196	          // Equip the best axe BEFORE EACH log — equip does not persist between digs.
1197	          try {
1198	            await bot.tool.equipForBlock(current, { requireHarvest: false });
1199	          } catch (err) {
1200	            stepCtx.log?.('warn', `chopTrees: equip axe failed at ${posKey(current.position)}: ${err.message}`);
1201	          }
1202	          try {
1203	            await safeDig(bot, current, stepCtx);
1204	            logsFelled++;
1205	          } catch (err) {
1206	            stepCtx.log?.('warn', `chopTrees: dig failed at ${posKey(current.position)}: ${err.message}`);
1207	            break;
1208	          }
1209	          current = bot.blockAt(current.position.offset(0, 1, 0));
1210	        }
1211	
1212	        if (logsFelled === 0) return { logsFelled: 0, collected: [] };
1213	
1214	        // Collect drops IMMEDIATELY — rival bots snipe drops within seconds.
