      const plankName = log.name.replace(/_log$/, '_planks');
      const logCount = itemCount(bot, log.name);
      await craftLocal(bot, plankName, Math.min(logCount, 4), ctx);
      planks = bot.inventory.items().find((it) => it.name.endsWith('_planks'));
